import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  FaBrain,
  FaClock,
  FaTasks,
  FaCalendarAlt,
  FaBolt,
  FaBookOpen
} from "react-icons/fa";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import AlertBox from "./AlertBox";
import "./theme.css";

function SmartPlannerAdvanced() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);
  const [targets, setTargets] = useState([]);
  const [alert, setAlert] = useState(null);

  const loadData = async () => {
    try {
      const p = await axios.get(`http://127.0.0.1:8000/planner/${userId}`);
      setPlans(p.data.plans || []);

      const t = await axios.get(`http://127.0.0.1:8000/smart-target/${userId}`);
      setTargets(t.data.targets || []);
    } catch (err) {
      console.error(err);
    }
  };

  const generatePlan = async () => {
    try {
      const res = await axios.post(
        `http://127.0.0.1:8000/smart-auto-plan/${userId}`
      );
      setAlert({
        message: res.data.message || "Smart plan generated successfully",
        type: "success"
      });
      loadData();
    } catch (err) {
      console.error(err);
      setAlert({ message: "Smart plan generation failed", type: "error" });
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const today = new Date().toISOString().split("T")[0];

  const pendingCount = plans.filter((p) => p.status === "Pending").length;
  const todayTasks = plans.filter((p) => p.study_date === today).length;

  return (
    <AppShell
      title="Smart Planner"
      subtitle="Generate deadline-aware study plans automatically from assignments and progress."
      action={
        <button className="btn btn-primary" onClick={generatePlan}>
          <FaBolt />
          Generate Smart Plan
        </button>
      }
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-4" style={{ marginBottom: "20px" }}>
        <div className="stat-card">
          <div className="dashboard-icon">
            <FaBrain />
          </div>
          <div className="stat-label">AI Mode</div>
          <div className="stat-value" style={{ fontSize: "28px" }}>
            Active
          </div>
          <div className="muted">Deadline-based planning</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon info">
            <FaTasks />
          </div>
          <div className="stat-label">Total Plans</div>
          <div className="stat-value">{plans.length}</div>
          <div className="muted">Manual + auto generated</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon warning">
            <FaClock />
          </div>
          <div className="stat-label">Pending</div>
          <div className="stat-value">{pendingCount}</div>
          <div className="muted">Remaining tasks</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon success">
            <FaCalendarAlt />
          </div>
          <div className="stat-label">Today Tasks</div>
          <div className="stat-value">{todayTasks}</div>
          <div className="muted">Scheduled for today</div>
        </div>
      </div>

      <div className="page-grid-2">
        <Panel title="Smart Targets">
          {targets.length === 0 ? (
            <div className="empty-state">
              <FaBrain />
              <h3>No smart targets</h3>
              <p className="muted">
                Add progress or assignments to generate target suggestions.
              </p>
            </div>
          ) : (
            <div className="planner-list">
              {targets.map((t, i) => (
                <div className="target-card" key={i}>
                  <div className="dashboard-icon info">
                    <FaBookOpen />
                  </div>

                  <h4>{t.course_title}</h4>
                  <p className="muted">Subject Code: {t.subject_code}</p>

                  <div className="target-grid">
                    <div>
                      <b>{t.target_topics_per_day}</b>
                      <span>Topics/day</span>
                    </div>
                    <div>
                      <b>{t.recommended_hours_per_day}</b>
                      <span>Hours/day</span>
                    </div>
                    <div>
                      <b>{t.remaining_topics}</b>
                      <span>Remaining</span>
                    </div>
                    <div>
                      <b>{t.days_left}</b>
                      <span>Days left</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Panel>

        <Panel title="Generated Plans">
          {plans.length === 0 ? (
            <div className="empty-state">
              <FaCalendarAlt />
              <h3>No plans generated</h3>
              <p className="muted">
                Click Generate Smart Plan to create study tasks automatically.
              </p>
            </div>
          ) : (
            <div className="planner-list">
              {plans.map((p) => (
                <div className="planner-card" key={p.id}>
                  <div className="planner-date">
                    <FaCalendarAlt />
                    <span>{p.study_date}</span>
                  </div>

                  <h4>{p.topic}</h4>

                  <span
                    className={
                      p.status === "Completed"
                        ? "badge badge-green"
                        : p.status === "Expired"
                        ? "badge badge-red"
                        : "badge badge-purple"
                    }
                  >
                    {p.status}
                  </span>
                </div>
              ))}
            </div>
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default SmartPlannerAdvanced;
